const tugas = [
  { id: 1, teks: 'Belajar JSX', selesai: true },
  { id: 2, teks: 'Belajar state', selesai: false },
  { id: 3, teks: 'Membuat todolist', selesai: false },
];

function FormTambah() {
  return (
    <form className="baris" onSubmit={(e) => e.preventDefault()}>
      <input type="text" placeholder="Tugas baru" />
      <button type="submit">Tambah</button>
    </form>
  );
}

function ItemTugas({ teks, selesai }) {
  return (
    <li className={selesai ? 'selesai' : ''}>
      <input type="checkbox" checked={selesai} readOnly />
      <span>{teks}</span>
    </li>
  );
}

function DaftarTugas({ isi }) {
  return (
    <ul className="daftar">
      {isi.map((t) => <ItemTugas key={t.id} teks={t.teks} selesai={t.selesai} />)}
    </ul>
  );
}

export default function App() {
  return (
    <div className="todo">
      <h1>Todolist</h1>
      <FormTambah />
      <DaftarTugas isi={tugas} />
    </div>
  );
}

